    moduli = inputs.get('moduli') or inputs.get('mods')

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    def chinese_remainder_theorem(remainders, moduli):
        total = 0
        prod = 1
        for m in moduli:
            prod *= m

        for r, m in zip(remainders, moduli):
            p = prod // m
            total += r * p * mod_inverse(p, m)

        return total % prod

    result = chinese_remainder_theorem(remainders, moduli)
    return float(result)

